    readonly alcoholSleep: number;
    readonly snackSleep: number;
    readonly nightShiftSleep: number;
    readonly slump: number;
    readonly slumpHours: number;
    readonly feverStudy: number;
    readonly coldStudy: number;
    readonly gastroStudy: number;
    readonly exerciseSleepBonus: number;
    readonly infBase: number;
    readonly chronicInf: number;
    readonly debtInf: number;
    readonly debtInfAt: number;
    readonly vaccineInf: number;
    readonly campusExposure: number;
    readonly restBed: number;
    readonly restEff: number;
    readonly feverIfEffBelow: number;
    readonly passMid: number;
    readonly passFin: number;
    readonly difficulty: number;
    readonly labHours: readonly number[];
    readonly shiftHours: readonly number[];
