export interface Difficulty {
  readonly name: string;
  /** Final-exam pass threshold multiplier. */
  readonly finMult: number;
  /** Minimum number of disruptive semester cards. */
  readonly minDisrupt: number;
  /** Opportunity events removed. */
  readonly oppRemove: number;
  /** Infection exposure multiplier. */
  readonly exposureMult: number;
  /** Sleep debt at the start, in hours. */
  readonly startDebt: number;
}

/** Schedule cards (docs/specs/content-spec.md section 1). Draft: the department demand fields of the spec belong to the removed token model (design doc status table) and are left out; the outer-layer work package settles the rest. */
export interface ScheduleCardsFile {
  readonly version: 1;
  readonly cards: readonly ScheduleCard[];
}

/** Changes to company metrics. study is academic progress, multiplied by study efficiency. */
export interface Metrics {
  readonly study?: number;
  readonly stress?: number;
  readonly social?: number;
  readonly hydration?: number;
}

export interface SleepRule {
  readonly ifHoursBeforeBedAtLeast?: number;
  readonly ifHoursBeforeBedLessThan?: number;
  /** Factor in that night's sleep efficiency product. */
  readonly sleepEfficiency: number;
}

export interface ScheduleCard {
  readonly id: string;
  readonly name: string;
  readonly slots: readonly ("morning" | "afternoon" | "evening" | "lateNight")[];
  /** Fixed length, or the lengths the player may choose from. */
  readonly hours: number | readonly number[];
  readonly perHour?: Metrics;
  /** Applied once when the card ends. */
  readonly once?: Metrics;
  readonly sleepRules?: readonly SleepRule[];
  readonly flavor: string;
  /** Handbook page id that unlocks the card, or null when always available. */
  readonly unlockedBy?: string | null;
  /** Handbook page id the card links to. */
  readonly handbook?: string;
}

/** Player-facing text for one language, keyed by string id. */
export interface StringsFile {
  readonly version: 1;
  readonly strings: Readonly<Record<string, StringEntry>>;
}

export interface StringEntry {
  readonly text: string;
  /** Fact-check table entry backing the text, or "" when it states no fact. */
  readonly fact: string;
}

/** State tag dictionary (design doc 13.4) and modifiers as condition aliases (8.7). Cross-checks (duplicate names, hours only with duration hours, unit only on number tags, modifier conditions) are in core/tags/dictionary.ts. */
export interface TagsFile {
  readonly version: 1;
  readonly tags: readonly Tag[];
  readonly modifiers: readonly Modifier[];
}

/** Fact-check table entry: a row number, "pending:<n>" for the pending list, or "general". */
export type Fact = string;

export interface Tag {
  readonly name: string;
  readonly type: "number" | "boolean";
  /** Display unit; number tags only. */
  readonly unit?: string;
  readonly sources: readonly ("card" | "event" | "chapter" | "rule")[];
  readonly duration: "persistent" | "hours" | "untilWake" | "nextDay";
  /** Span in rule hours; required with duration "hours" and only then. */
  readonly hours?: number;
  readonly facts: readonly Fact[];
}

export interface Modifier {
  readonly name: string;
  /** Condition over tags only (no modifier may use another). */
  readonly when: string;
  readonly facts: readonly Fact[];
}
